diff --git a/js/common/machineAuthor.js b/js/common/machineAuthor.js
index 3a550fb9..4fdc1dd1 100644
--- a/js/common/machineAuthor.js
+++ b/js/common/machineAuthor.js
@@ -67,23 +67,37 @@ function machineAuthorLogins(machineAuthor) {
     return out;
 }

+// gh-1025 (live 2026-10-18, SM tick 39103844372): GitHub reports App
+// authors WITH a `[bot]` suffix (`dmtools-factory-bot[bot]`) while the
+// deployment knob lists the bare login (`dmtools-factory-bot`, added by
+// #988 — which therefore never matched). Every prMachineAuthor SM rule
+// failed closed for ~8h: zero rework legs, zero arms, queue silently
+// dead. Comparisons strip ONE trailing `[bot]` (case-insensitive) from
+// both sides; a bare `bot` ending without brackets (`robot`) is never
+// touched, and different bots still never match (`dependabot[bot]` !=
+// `dmtools-factory-bot`).
+function stripBotSuffix(login) {
+    return String(login || '').replace(/\[bot\]$/i, '');
+}
+
 /**
  * Case-insensitive membership test for ACTOR probes (the sticky-park
  * RESET in smAgent.js): those have always lowercase-compared the head
  * commit's GitHub login against the machine login — with a list, a push
  * by ANY entry is machine movement (the park survives every machine
- * login's push, not just the first one's).
+ * login's push, not just the first one's). The `[bot]` suffix is
+ * normalized on both sides (gh-1025).
  *
  * @param {string|null} login      the actor/committer login to test
  * @param {string|null} machineAuthor raw resolveMachineAuthor output
  * @returns {boolean} true when login matches any list entry
  */
 function isMachineLogin(login, machineAuthor) {
-    var l = String(login || '').toLowerCase();
+    var l = stripBotSuffix(String(login || '').toLowerCase());
     if (!l) return false;
     var entries = machineAuthorLogins(machineAuthor);
     for (var i = 0; i < entries.length; i++) {
-        if (entries[i].toLowerCase() === l) return true;
+        if (stripBotSuffix(entries[i].toLowerCase()) === l) return true;
     }
     return false;
 }
@@ -135,7 +149,15 @@ function isMachineReleaseBump(item, owner) {
  */
 function isMachineAuthored(item, machineAuthor, owner) {
     var author = itemAuthor(item);
-    if (author && machineAuthorLogins(machineAuthor).indexOf(author) !== -1) return true;
+    if (author) {
+        // gh-1025: the bare login part stays case-SENSITIVE (design);
+        // only the API's App `[bot]` suffix is normalized away.
+        var bareAuthor = stripBotSuffix(author);
+        var entries = machineAuthorLogins(machineAuthor);
+        for (var i = 0; i < entries.length; i++) {
+            if (stripBotSuffix(entries[i]) === bareAuthor) return true;
+        }
+    }
     return isMachineReleaseBump(item, owner);
 }

diff --git a/js/unit-tests/test_machineAuthor.js b/js/unit-tests/test_machineAuthor.js
index 205fe894..db009f36 100644
--- a/js/unit-tests/test_machineAuthor.js
+++ b/js/unit-tests/test_machineAuthor.js
@@ -149,3 +149,51 @@ suite('common/machineAuthor: isMachineLogin — case-insensitive list membership
         assert.ok(!isLogin('ai-teammate', ''));
     });
 });
+
+suite('common/machineAuthor: GitHub App [bot] suffix normalization (gh-1025)', function () {
+
+    // Live 2026-10-18 (SM tick 39103844372): #988 added 'dmtools-factory-bot'
+    // to the knob, but GitHub reports App-authored PRs as
+    // 'dmtools-factory-bot[bot]'. Exact match failed → every prMachineAuthor
+    // rule fail-closed: zero rework legs dispatched, zero arms landed, the
+    // whole agents queue silently dead for ~8h while labels looked armed.
+    var mod = loadModule('js/common/machineAuthor.js', makeRequire({}), {});
+    var isMachine = mod.isMachineAuthored;
+    var isLogin = mod.isMachineLogin;
+
+    test('configured bare login matches the API-reported [bot] author', function () {
+        assert.ok(isMachine({ author: 'dmtools-factory-bot[bot]' },
+            'ai-teammate,dmtools-factory-bot', 'owner'));
+    });
+
+    test('configured [bot] entry matches a bare author (both directions)', function () {
+        assert.ok(isMachine({ author: 'dmtools-factory-bot' },
+            'ai-teammate,dmtools-factory-bot[bot]', 'owner'));
+    });
+
+    test('exact [bot]-to-[bot] match still works (github-actions[bot] back-compat)', function () {
+        assert.ok(isMachine({ author: 'github-actions[bot]' },
+            'ai-teammate,github-actions[bot]', 'owner'));
+    });
+
+    test('isMachineLogin normalizes the suffix too (actor probes)', function () {
+        assert.ok(isLogin('dmtools-factory-bot[bot]', 'dmtools-factory-bot'));
+        assert.ok(isLogin('dmtools-factory-bot', 'dmtools-factory-bot[bot]'));
+        assert.ok(isLogin('DMTOOLS-FACTORY-BOT[bot]', 'dmtools-factory-bot'));
+    });
+
+    test('a bare suffix without brackets is NOT stripped (robot != ro[bot])', function () {
+        assert.ok(!isMachine({ author: 'robot' }, 'ro', 'owner'));
+        assert.ok(!isMachine({ author: 'ro' }, 'robot', 'owner'));
+    });
+
+    test('a DIFFERENT bot still does not match (normalization is not a wildcard)', function () {
+        assert.ok(!isMachine({ author: 'dependabot[bot]' }, 'dmtools-factory-bot', 'owner'));
+        assert.ok(!isMachine({ author: 'dmtools-factory-bot2[bot]' }, 'dmtools-factory-bot', 'owner'));
+        assert.ok(!isLogin('other-bot[bot]', 'dmtools-factory-bot'));
+    });
+
+    test('case-sensitivity of the bare login part is preserved in isMachineAuthored (design)', function () {
+        assert.ok(!isMachine({ author: 'DMTOOLS-FACTORY-BOT[bot]' }, 'dmtools-factory-bot', 'owner'));
+    });
+});
